				from
				  %s.%s
				force index (%s)
					where (%s = %s and %s %s %s and %s <= %s)
					%s
			)`,
			databaseName, originalTableName,
			databaseName, ghostTableName, mappedSharedColumnsListing,
			sharedColumnsListing,
