		select /* gh-ost %s.%s */ %s
		from
			%s.%s
		force index (%s)
		where
			(%s and %s)
		`,
		sourceDatabaseName, sourceTableName, sharedColumnsListing,
		sourceDatabaseName, sourceTableName,
		uniqueKey,
		rangeStartComparison, rangeEndComparison,
	)
