	if mctx.ForceTmpTableName != "" {
		tableName = mctx.ForceTmpTableName
	} else {
		tableName = mctx.OriginalTableName
	}

	suffix := "del"
	if mctx.Revert {
		suffix = "rev_del"
	}
	if mctx.TimestampOldTable {
		t := mctx.StartTime
		timestamp := fmt.Sprintf("%d%02d%02d%02d%02d%02d",
