func sameFirstColumnValue(rangeStartArgs, rangeEndArgs []interface{}) bool {
	if len(rangeStartArgs) == 0 || len(rangeEndArgs) == 0 {
		return false
	}
	return fmt.Sprintf("%v", rangeStartArgs[0]) == fmt.Sprintf("%v", rangeEndArgs[0])
