	args := make([]interface{}, 0, b.sharedColumns.Len()+b.uniqueKeyColumns.Len())
	for _, column := range b.sharedColumns.Columns() {
		tableOrdinal := b.tableColumns.Ordinals[column.Name]
		arg := column.convertArg(valueArgs[tableOrdinal])
