		vx.GBPApplied = true
	}

	vx.GBPGroupPolicyID = binary.BigEndian.Uint16(data[2:4])

	vxlanLength := 8
	vx.Contents = data[:vxlanLength]
	vx.Payload = data[vxlanLength:]
	p.AddLayer(vx)
	return p.NextDecoder(LinkType(1))
}

